206	/**
207	  * @brief  Initializes the DSI LCD. 
208	    * The initialization is done as below:
209	    *     - DSI PLL initialization
210	    *     - DSI initialization
211	    *     - LTDC initialization
212	    *     - OTM8009A LCD Display IC Driver initialization
213	  * @retval LCD state
214	  */
215	uint8_t BSP_LCD_InitEx(LCD_OrientationTypeDef orientation)
216	{
217	  DSI_PLLInitTypeDef dsiPllInit;
218	  DSI_PHY_TimerTypeDef  PhyTimings;
219	  static RCC_PeriphCLKInitTypeDef  PeriphClkInitStruct;
220	  uint32_t LcdClock  = 27429; /*!< LcdClk = 27429 kHz */
221	  
222	  uint32_t laneByteClk_kHz = 0;
223	  uint32_t                   VSA; /*!< Vertical start active time in units of lines */
224	  uint32_t                   VBP; /*!< Vertical Back Porch time in units of lines */
225	  uint32_t                   VFP; /*!< Vertical Front Porch time in units of lines */
226	  uint32_t                   VACT; /*!< Vertical Active time in units of lines = imageSize Y in pixels to display */
227	  uint32_t                   HSA; /*!< Horizontal start active time in units of lcdClk */
228	  uint32_t                   HBP; /*!< Horizontal Back Porch time in units of lcdClk */
229	  uint32_t                   HFP; /*!< Horizontal Front Porch time in units of lcdClk */
230	  uint32_t                   HACT; /*!< Horizontal Active time in units of lcdClk = imageSize X in pixels to display */
231	  
232	  
233	  /* Toggle Hardware Reset of the DSI LCD using
234	  * its XRES signal (active low) */
235	  BSP_LCD_Reset();
236	  
237	  /* Call first MSP Initialize only in case of first initialization
238	  * This will set IP blocks LTDC, DSI and DMA2D
239	  * - out of reset
240	  * - clocked
241	  * - NVIC IRQ related to IP blocks enabled
242	  */
243	  BSP_LCD_MspInit();
244	  
245	/*************************DSI Initialization***********************************/  
246	  
247	  /* Base address of DSI Host/Wrapper registers to be set before calling De-Init */
248	  hdsi_eval.Instance = DSI;
249	  
250	  HAL_DSI_DeInit(&(hdsi_eval));
251	  
252	#if !defined(USE_STM32469I_DISCO_REVA)
253	  dsiPllInit.PLLNDIV  = 125;
254	  dsiPllInit.PLLIDF   = DSI_PLL_IN_DIV2;
255	  dsiPllInit.PLLODF   = DSI_PLL_OUT_DIV1;
256	#else  
257	  dsiPllInit.PLLNDIV  = 100;
258	  dsiPllInit.PLLIDF   = DSI_PLL_IN_DIV5;
259	  dsiPllInit.PLLODF   = DSI_PLL_OUT_DIV1;

260	#endif
261	  laneByteClk_kHz = 62500; /* 500 MHz / 8 = 62.5 MHz = 62500 kHz */
262	  
263	  /* Set number of Lanes */
264	  hdsi_eval.Init.NumberOfLanes = DSI_TWO_DATA_LANES;
265	  
266	  /* TXEscapeCkdiv = f(LaneByteClk)/15.62 = 4 */
267	  hdsi_eval.Init.TXEscapeCkdiv = laneByteClk_kHz/15620; 
268	  
269	  HAL_DSI_Init(&(hdsi_eval), &(dsiPllInit));
270	
271	  /* Start DSI */
272	  HAL_DSI_Start(&hdsi_eval);
273	  /* Enable the DSI BTW for read operations */
274	  HAL_DSI_ConfigFlowControl(&hdsi_eval, DSI_FLOW_CONTROL_BTA);
275	  Lcd_Driver_Type = LCD_ReadType(Lcd_Driver_Type);
276	
277	  /* Do trang thai panel OTM8009A o che do Command Mode (truoc khi vao Video Mode) */
278	  if (Lcd_Driver_Type == LCD_CTRL_OTM8009A)
279	  {
280	    /* Gui lenh bat man hinh o che do Command Mode */
281	    HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x11, 0x00); /* Sleep Out */
282	    HAL_Delay(120);
283	
284	    /* Phep thu phan dinh do sang: doc ban dau, ghi 0x88, doc lai */
285	    extern volatile uint8_t  g_bright_before;
286	    extern volatile uint8_t  g_bright_val_written;
287	    extern volatile uint8_t  g_bright_after;
288	    extern volatile uint32_t g_bright_write_ret;
289	    extern volatile int32_t  g_bright_read_ret;
290	
291	    /* Doc gia tri do sang ban dau truoc khi ghi */
292	    DSI_IO_ReadCmd(0x52, (uint8_t *)&g_bright_before, 1);
293	
294	    /* Ghi gia tri do sang test moi (0x88) */
295	    g_bright_val_written = 0x88;
296	    g_bright_write_ret = (uint32_t)HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x51, g_bright_val_written); /* WRDISBV */
297	    HAL_Delay(10);
298	
299	    /* Doc lai dung thanh ghi do sang 0x52 ngay sau khi ghi */
300	    g_bright_read_ret = DSI_IO_ReadCmd(0x52, (uint8_t *)&g_bright_after, 1);
301	
302	    HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x53, 0x2C); /* WRCTRLD */
303	    HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x29, 0x00); /* Display On */
304	    HAL_Delay(50);
305	
306	    /* Doc cac thanh ghi DCS cua panel OTM8009A */
307	    g_panel_cmd_ret[0] = DSI_IO_ReadCmd(0xDA, (uint8_t *)&g_panel_cmd_status[0], 1); /* ID1 (0x80) */
308	    g_panel_cmd_ret[1] = DSI_IO_ReadCmd(0x0A, (uint8_t *)&g_panel_cmd_status[1], 1); /* Power Mode */
309	    g_panel_cmd_ret[2] = DSI_IO_ReadCmd(0x0B, (uint8_t *)&g_panel_cmd_status[2], 1); /* MADCTL */
310	    g_panel_cmd_ret[3] = DSI_IO_ReadCmd(0x0C, (uint8_t *)&g_panel_cmd_status[3], 1); /* COLMOD */
311	    g_panel_cmd_ret[4] = DSI_IO_ReadCmd(0x52, (uint8_t *)&g_panel_cmd_status[4], 1); /* Brightness */
312	    g_panel_cmd_ret[5] = DSI_IO_ReadCmd(0x54, (uint8_t *)&g_panel_cmd_status[5], 1); /* CTRL Display */
313	    g_panel_cmd_ret[6] = DSI_IO_ReadCmd(0x0F, (uint8_t *)&g_panel_cmd_status[6], 1); /* Self-Diagnostic */
314	    g_panel_cmd_ret[7] = DSI_IO_ReadCmd(0x0D, (uint8_t *)&g_panel_cmd_status[7], 1); /* Image Mode */
315	  }
316	
317	  BSP_LCD_Reset();
318	  HAL_DSI_Stop(&hdsi_eval);
319

318	  HAL_DSI_Stop(&hdsi_eval);
319	
320	  /* Timing parameters for all Video modes
321	  * Set Timing parameters of LTDC depending on its chosen orientation
322	  */
323	  if(orientation == LCD_ORIENTATION_PORTRAIT)
324	  {
325	    lcd_x_size = OTM8009A_480X800_WIDTH;  /* 480 */
326	    lcd_y_size = OTM8009A_480X800_HEIGHT; /* 800 */                                
327	  }
328	  else
329	  {
330	    /* lcd_orientation == LCD_ORIENTATION_LANDSCAPE */
331	    lcd_x_size = OTM8009A_800X480_WIDTH;  /* 800 */
332	    lcd_y_size = OTM8009A_800X480_HEIGHT; /* 480 */                                
333	  }
334	  
335	  HACT = lcd_x_size;
336	  VACT = lcd_y_size;
337	  
338	  /* The following values are same for portrait and landscape orientations */
339	  if (Lcd_Driver_Type == LCD_CTRL_NT35510)
340	  {
341	    VSA  = NT35510_480X800_VSYNC;
342	    VBP  = NT35510_480X800_VBP;
343	    VFP  = NT35510_480X800_VFP;
344	    HSA  = NT35510_480X800_HSYNC;
345	    HBP  = NT35510_480X800_HBP;
346	    HFP  = NT35510_480X800_HFP;
347	  }
348	  else
349	  {
350	    VSA  = OTM8009A_480X800_VSYNC;
351	    VBP  = OTM8009A_480X800_VBP;
352	    VFP  = OTM8009A_480X800_VFP;
353	    HSA  = OTM8009A_480X800_HSYNC;
354	    HBP  = OTM8009A_480X800_HBP;
355	    HFP  = OTM8009A_480X800_HFP;
356	  }
357	
358	  hdsivideo_handle.VirtualChannelID = LCD_Driver_ID;
359	  hdsivideo_handle.ColorCoding = LCD_DSI_PIXEL_DATA_FMT_RBG888;
360	  hdsivideo_handle.VSPolarity = DSI_VSYNC_ACTIVE_HIGH;
361	  hdsivideo_handle.HSPolarity = DSI_HSYNC_ACTIVE_HIGH;
362	  hdsivideo_handle.DEPolarity = DSI_DATA_ENABLE_ACTIVE_HIGH;  
363	  hdsivideo_handle.Mode = DSI_VID_MODE_BURST; /* Mode Video burst ie : one LgP per line */
364	  hdsivideo_handle.NullPacketSize = 0xFFF;
365	  hdsivideo_handle.NumberOfChunks = 0;
366	  hdsivideo_handle.PacketSize                = HACT; /* Value depending on display orientation choice portrait/landscape */ 
367	  hdsivideo_handle.HorizontalSyncActive      = (HSA * laneByteClk_kHz) / LcdClock;
368	  hdsivideo_handle.HorizontalBackPorch       = (HBP * laneByteClk_kHz) / LcdClock;
369	  hdsivideo_handle.HorizontalLine            = ((HACT + HSA + HBP + HFP) * laneByteClk_kHz) / LcdClock; /* Value depending on display orientation choice portrait/landscape */
370	  hdsivideo_handle.VerticalSyncActive        = VSA;
371	  hdsivideo_handle.VerticalBackPorch         = VBP;
372	  hdsivideo_handle.VerticalFrontPorch        = VFP;
373	  hdsivideo_handle.VerticalActive            = VACT; /* Value depending on display orientation choice portrait/landscape */
374	  
375	  /* Enable or disable sending LP command while streaming is active in video mode */
376	  hdsivideo_handle.LPCommandEnable = DSI_LP_COMMAND_ENABLE; /* Enable sending commands in mode LP (Low Power) */
377

378	  /* Largest packet size possible to transmit in LP mode in VSA, VBP, VFP regions */
379	  /* Only useful when sending LP packets is allowed while streaming is active in video mode */
380	  hdsivideo_handle.LPLargestPacketSize = 16;
381	  
382	  /* Largest packet size possible to transmit in LP mode in HFP region during VACT period */
383	  /* Only useful when sending LP packets is allowed while streaming is active in video mode */
384	  hdsivideo_handle.LPVACTLargestPacketSize = 0;
385	  
386	  
387	  /* Specify for each region of the video frame, if the transmission of command in LP mode is allowed in this region */
388	  /* while streaming is active in video mode                                                                         */
389	  hdsivideo_handle.LPHorizontalFrontPorchEnable = DSI_LP_HFP_ENABLE;   /* Allow sending LP commands during HFP period */
390	  hdsivideo_handle.LPHorizontalBackPorchEnable  = DSI_LP_HBP_ENABLE;   /* Allow sending LP commands during HBP period */
391	  hdsivideo_handle.LPVerticalActiveEnable = DSI_LP_VACT_ENABLE;  /* Allow sending LP commands during VACT period */
392	  hdsivideo_handle.LPVerticalFrontPorchEnable = DSI_LP_VFP_ENABLE;   /* Allow sending LP commands during VFP period */
393	  hdsivideo_handle.LPVerticalBackPorchEnable = DSI_LP_VBP_ENABLE;   /* Allow sending LP commands during VBP period */
394	  hdsivideo_handle.LPVerticalSyncActiveEnable = DSI_LP_VSYNC_ENABLE; /* Allow sending LP commands during VSync = VSA period */
395	  
396	  /* Configure DSI Video mode timings with settings set above */
397	  HAL_DSI_ConfigVideoMode(&(hdsi_eval), &(hdsivideo_handle));
398	
399	  /* Configure DSI PHY HS2LP and LP2HS timings */
400	  PhyTimings.ClockLaneHS2LPTime = 35;
401	  PhyTimings.ClockLaneLP2HSTime = 35;
402	  PhyTimings.DataLaneHS2LPTime = 35;
403	  PhyTimings.DataLaneLP2HSTime = 35;
404	  PhyTimings.DataLaneMaxReadTime = 0;
405	  PhyTimings.StopWaitTime = 10;
406	  HAL_DSI_ConfigPhyTimer(&hdsi_eval, &PhyTimings);
407	
408	/*************************End DSI Initialization*******************************/ 
409	
410	
411	/************************LTDC Initialization***********************************/  
412	  
413	  /* Timing Configuration */    
414	  hltdc_eval.Init.HorizontalSync = (HSA - 1);
415	  hltdc_eval.Init.AccumulatedHBP = (HSA + HBP - 1);
416	  hltdc_eval.Init.AccumulatedActiveW = (lcd_x_size + HSA + HBP - 1);
417	  hltdc_eval.Init.TotalWidth = (lcd_x_size + HSA + HBP + HFP - 1);
418	  
419	  /* Initialize the LCD pixel width and pixel height */
420	  hltdc_eval.LayerCfg->ImageWidth  = lcd_x_size;
421	  hltdc_eval.LayerCfg->ImageHeight = lcd_y_size;   
422	  
423	  
424	  /* LCD clock configuration */
425	  /* PLLSAI_VCO Input = HSE_VALUE/PLL_M = 1 Mhz */
426	  /* PLLSAI_VCO Output = PLLSAI_VCO Input * PLLSAIN = 384 Mhz */
427	  /* PLLLCDCLK = PLLSAI_VCO Output/PLLSAIR = 384 MHz / 7 = 54.857 MHz */
428	  /* LTDC clock frequency = PLLLCDCLK / LTDC_PLLSAI_DIVR_2 = 54.857 MHz / 2 = 27.429 MHz */
429	  PeriphClkInitStruct.PeriphClockSelection = RCC_PERIPHCLK_LTDC;
430	  PeriphClkInitStruct.PLLSAI.PLLSAIN = 384;
431	  PeriphClkInitStruct.PLLSAI.PLLSAIR = 7;
432	  PeriphClkInitStruct.PLLSAIDivR = RCC_PLLSAIDIVR_2;
433	  HAL_RCCEx_PeriphCLKConfig(&PeriphClkInitStruct); 
434	  
435	  /* Background value */
436	  hltdc_eval.Init.Backcolor.Blue = 0;
437	  hltdc_eval.Init.Backcolor.Green = 0;

470	  }
471	  else if (Lcd_Driver_Type == LCD_CTRL_OTM8009A)
472	  {
