498	/**
499	  * @brief  BSP LCD Reset
500	  *         Hw reset the LCD DSI activating its XRES signal (active low for some time)
501	  *         and desactivating it later.
502	  *         This signal is only cabled on Discovery Rev B and beyond.
503	  */
504	void BSP_LCD_Reset(void)
505	{
506	#if !defined(USE_STM32469I_DISCO_REVA)
507	  /* Disco Rev B and beyond : reset the LCD by activation of XRES (active low) connected to PH7 */
508	  GPIO_InitTypeDef  gpio_init_structure;
509	
510	  __HAL_RCC_GPIOH_CLK_ENABLE();
511	
512	  /* Configure the GPIO on PH7 */
513	  gpio_init_structure.Pin   = GPIO_PIN_7;
514	  gpio_init_structure.Mode  = GPIO_MODE_OUTPUT_PP;
515	  gpio_init_structure.Pull  = GPIO_PULLUP;
516	  gpio_init_structure.Speed = GPIO_SPEED_HIGH;
517	
518	  HAL_GPIO_Init(GPIOH, &gpio_init_structure);
519	
520	  /* Activate XRES active low */
521	  HAL_GPIO_WritePin(GPIOH, GPIO_PIN_7, GPIO_PIN_RESET);
522	
523	  HAL_Delay(20); /* wait 20 ms */
524	
525	  /* Deactivate XRES */
526	  HAL_GPIO_WritePin(GPIOH, GPIO_PIN_7, GPIO_PIN_SET);
527	
528	  /* Wait for 20ms after releasing XRES before sending commands */
529	  HAL_Delay(20);

 70	#define NT35510_480X800_HSYNC  OTM8009A_480X800_HSYNC
