 77	uint16_t NT35510_ReadID(void)
 78	{
 79	  uint8_t id1 = 0, id2 = 0;
 80	  if ((DSI_IO_ReadCmd(0xDA, &id1, 1) == LCD_OK) && (DSI_IO_ReadCmd(0xDB, &id2, 1) == LCD_OK))
 81	  {
 82	    return (uint16_t)((id1 << 8) | id2);
 83	  }
 84	  return 0;
 85	}
